import { useMutation, useQueryClient } from '@tanstack/react-query';

const useRefreshToken = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async () => {
      const response = await fetch('/api/auth/refresh', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          refreshToken: getRefreshToken()
        })
      });

      if (!response.ok) {
        throw new Error('Refresh failed');
      }

      return response.json();
    },
    onSuccess: (data) => {
      queryClient.setQueryData(['auth'], data);
    }
  });
};

const authFetch = async (url: string, options: RequestInit = {}) => {
  const token = getAccessToken();

  let response = await fetch(url, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${token}`,
      ...options.headers
    }
  });

  if (response.status === 401) {
    const refreshToken = getRefreshToken();
    const refreshResponse = await fetch('/api/auth/refresh', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refreshToken })
    });

    if (refreshResponse.ok) {
      const { accessToken } = await refreshResponse.json();
      setAccessToken(accessToken);

      response = await fetch(url, {
        ...options,
        headers: {
          ...options.headers,
          Authorization: `Bearer ${accessToken}`
        }
      });
    }
  }

  return response;
};

const useLogin = () => {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (credentials) => {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(credentials)
      });

      if (!response.ok) {
        throw new Error('Login failed');
      }

      return response.json();
    },
    onSuccess: (data) => {
      setAccessToken(data.accessToken);
      setRefreshToken(data.refreshToken);

      queryClient.setQueryData(['auth'], data.user);
      queryClient.invalidateQueries({ queryKey: ['protected'] });
    },
    onError: () => {
      clearTokens();
    }
  });
};

const useProtectedQuery = <T>({
  queryKey,
  queryFn
}: UseQueryOptions<T>) => {
  const { data: auth } = useQuery({ queryKey: ['auth'] });

  return useQuery({
    queryKey,
    queryFn: async () => {
      const response = await authFetch(queryFn.toString());
      if (!response.ok) throw new Error('Protected request failed');
      return response.json() as Promise<T>;
    },
    enabled: !!auth,
    retry: (failureCount, error) => {
      if (error.message.includes('401')) return false;
      return failureCount < 3;
    }
  });
};
